#"'!/usr/bin/env python3

import argparse
import json
import os
import sys
import urllib.error
import urllib.request


API_URL = "https://api.openai.com/v1/responses"
DEFAULT_MODEL = os.environ.get("OPENAI_MODEL", "gpt-4.1-mini")
DEFAULT_TIMEOUT = 120.0


class ResponsesAPIError(RuntimeError):
    def __init__(self, status, message, details=None):
        super().__init__(message)
        self.status = status
        self.details = details


def _extract_output_text(response):
    if not isinstance(response, dict):
        raise ResponsesAPIError(None, "Responses API returned an invalid JSON object")

    error = response.get("error")
    if error:
        message = error.get("message", "Responses API request failed") if isinstance(error, dict) else str(error)
        raise ResponsesAPIError(response.get("status"), message, error)

    if isinstance(response.get("output_text"), str):
        return response["output_text"]

    output = response.get("output")
    if isinstance(output, str):
        return output
    if not isinstance(output, list):
        raise ResponsesAPIError(response.get("status"), "Responses API response contains no output")

    text_parts = []
    for item in output:
        if not isinstance(item, dict) or item.get("type") != "message":
            continue
        content = item.get("content")
        if not isinstance(content, list):
            continue
        for block in content:
            if isinstance(block, dict) and block.get("type") in {"output_text", "text"}:
                text = block.get("text")
                if isinstance(text, str):
                    text_parts.append(text)

    if not text_parts:
        raise ResponsesAPIError(response.get("status"), "Responses API response contains no output text")
    return "'"\\n\".join(text_parts)


def send_prompt(prompt, model=None, api_key=None, timeout=None, store=False):
    if not isinstance(prompt, str) or not prompt:
        raise ValueError(\"prompt must be a non-empty string\")

    selected_model = model or DEFAULT_MODEL
    selected_api_key = api_key or os.environ.get(\"OPENAI_API_KEY\")
    selected_timeout = DEFAULT_TIMEOUT if timeout is None else timeout
    if not selected_api_key:
        raise RuntimeError(\"OPENAI_API_KEY is not set\")
    if not selected_model:
        raise ValueError(\"model must be a non-empty string\")
    if selected_timeout <= 0:
        raise ValueError(\"timeout must be greater than zero\")

    request_body = json.dumps(
        {\"model\": selected_model, \"input\": prompt, \"store\": store},
        ensure_ascii=False,
    ).encode(\"utf-8\")
    request = urllib.request.Request(
        API_URL,
        data=request_body,
        headers={
            \"Authorization\": f\"Bearer {selected_api_key}\",
            \"Content-Type\": \"application/json\",
            \"User-Agent\": \"openai-client.py/1.0\",
        },
        method=\"POST\",
    )

    try:
        with urllib.request.urlopen(request, timeout=selected_timeout) as api_response:
            response_data = json.loads(api_response.read().decode(\"utf-8\"))
    except urllib.error.HTTPError as error:
        raw_body = error.read().decode(\"utf-8\", errors=\"replace\")
        try:
            error_body = json.loads(raw_body)
        except json.JSONDecodeError:
            error_body = {\"message\": raw_body}
        details = error_body.get(\"error\", error_body) if isinstance(error_body, dict) else error_body
        message = details.get(\"message\", raw_body or str(error)) if isinstance(details, dict) else str(details)
        raise ResponsesAPIError(error.code, message, details) from None
    except (urllib.error.URLError, TimeoutError) as error:
        reason = getattr(error, \"reason\", error)
        raise ResponsesAPIError(None, f\"Could not reach Responses API: {reason}\") from None
    except json.JSONDecodeError as error:
        raise ResponsesAPIError(None, \"Responses API returned invalid JSON\") from error

    return _extract_output_text(response_data)


def _read_prompt(args_prompt):
    if args_prompt:
        return \" \".join(args_prompt)
    if not sys.stdin.isatty():
        return sys.stdin.read().strip()
    return input(\"Private prompt: \").strip()


def main(argv=None):
    parser = argparse.ArgumentParser(description=\"Send a text prompt to OpenAI's Responses API.\")
    parser.add_argument(\"prompt\", nargs=\"*\", help=\"Prompt text. Omit to read it from stdin.\")
    parser.add_argument(\"--model\", default=DEFAULT_MODEL, help=\"Model name (default: OPENAI_MODEL or gpt-4.1-mini).\")
    parser.add_argument(\"--store\", action=\"store_true\", help=\"Allow OpenAI to store the prompt and response.\")
    parser.add_argument(\"--timeout\", type=float, default=DEFAULT_TIMEOUT, help=\"Request timeout in seconds.\")
    args = parser.parse_args(argv)

    prompt = _read_prompt(args.prompt)
    if not prompt:
        parser.error(\"prompt must not be empty\")

    try:
        print(send_prompt(prompt, model=args.model, timeout=args.timeout, store=args.store))
    except (ResponsesAPIError, RuntimeError, ValueError) as error:
        print(f\"Error: {error}\", file=sys.stderr)
        return 1
    return 0


if __name__ == \"__main__\":
    raise SystemExit(main())
